#define SHADER "#include <metal_stdlib>\nusing namespace metal;\nstruct V{float4 p [[position]];};\nvertex V vert(uint i [[vertex_id]]){float2 p=float2((i<<1)&2,i&2);return {float4(p*2-1,0,1)};}\nfloat2 rot(float2 p,float a){return float2(cos(a)*p.x-sin(a)*p.y,sin(a)*p.x+cos(a)*p.y);}\nfloat3 pal(float x){return .5+.5*cos(6.283185*(x+float3(0.,.33,.67)));}\nfloat ln(float d,float w){return w/(abs(d)+w);}\nfragment float4 frag(V v [[stage_in]],constant float3 &u [[buffer(0)]]){\n float t=u.z;float2 uv=(v.p.xy*2-u.xy)/u.y;float r=length(uv);float scene=floor(t/32.),lt=fmod(t,32.);float3 c=0.;\n if(scene<1.){for(int i=0;i<9;i++){float f=float(i),phase=f*6.283/9.+lt*(.17+.012*f);float2 ctr=float2(.55*cos(phase),.38*sin(phase*1.3));float2 q=uv-ctr;float a=atan2(q.y,q.x);float tooth=abs(fract(a*8./6.283+.5)-.5);float gear=abs(length(q)-(.09+.025*step(.27,tooth)));c+=pal(f*.1+lt*.02)*ln(gear,.004)*.06;float hub=abs(length(q)-.025);c+=pal(f*.1)*ln(hub,.003)*.035;}}else if(scene<2.){float2 p=rot(uv,lt*.08);for(int i=0;i<13;i++){float f=float(i),ph=f*2.399+lt*(.11+.003*f);float2 q=rot(p-float2(.4*sin(ph),.3*cos(ph*1.4)),ph);float grid=abs(fract((q.x+q.y*.7)*11.)-.5);c+=pal(f*.07+lt*.018)*ln(grid,.035)*.025;}}else{for(int i=0;i<15;i++){float f=float(i),phase=f*6.283/15.+lt*.21;float2 ctr=float2(.72*cos(phase),.5*sin(phase*1.1));float2 q=uv-ctr;float d=abs(max(abs(q.x)-.025,abs(q.y)-.025));c+=pal(f*.08+lt*.02)*ln(d,.003)*.05;}float2 p=rot(uv,lt*.04);float gear=abs(length(p)-(.28+.04*cos(atan2(p.y,p.x)*10.-lt*.3)));c+=pal(lt*.02)*ln(gear,.005)*.1;}\n c*=1.-.18*smoothstep(.25,1.7,r);c=1.-exp(-max(c,0.)*1.8);c=pow(c,float3(.82));float fade=smoothstep(0.,2.,t)*(1.-smoothstep(94.,96.,t));c*=fade;return float4(c,1.);}\n"
